package com.game_manager.gm.ai;
import static org.assertj.core.api.Assertions.*;import java.net.URI;import java.time.*;import org.junit.jupiter.api.Test;import tools.jackson.databind.ObjectMapper;
class HttpAiSummaryProviderTest {@Test void opensCircuitAfterConsecutiveProviderFailures(){AiProperties config=new AiProperties("http",URI.create("https://127.0.0.1:1"),"external-secret","model",100,200,100,1000,2,60,90);HttpAiSummaryProvider provider=new HttpAiSummaryProvider(config,new ObjectMapper(),Clock.fixed(Instant.parse("2026-08-10T10:00:00Z"),ZoneOffset.UTC),new AiOutputPolicy());AiSummaryProvider.Input input=new AiSummaryProvider.Input("v1","orders",1,"2026-08-10T09:00:00Z",100);assertThatThrownBy(()->provider.summarize(input)).isInstanceOf(AiProviderException.class);assertThatThrownBy(()->provider.summarize(input)).isInstanceOf(AiProviderException.class);assertThatThrownBy(()->provider.summarize(input)).isInstanceOf(AiProviderException.class).hasMessageContaining("circuit is open");}}
